import React, { useEffect, useState } from 'react';
import { Box, Typography, Card, CardContent, Button, Stack, AppBar } from '@mui/material';
import MinimalAppBar from '../../Component/MinimalAppBar';
import callApi from '../../Services/callApi';

const LoanScreen = () => {
  const [data, setData] = useState<any[]>([]);

  useEffect(() => {
    onLoad();
  }, [])

  const onLoad = async () => {
    var res = await callApi.get('/personalloan/myloan');
    if (res.data?.success) {
      setData(res.data?.data);
    }
  }
  return (
    <>
      <MinimalAppBar onBack={() => window.history.back} title="สินเชื่อของฉัน"></MinimalAppBar>
      <Box p={3} bgcolor="background.primary" sx={{
    display: 'flex',
    overflowX: 'auto',
    gap: 2,
    padding: 2,
    scrollSnapType: 'x mandatory',
    '&::-webkit-scrollbar': { display: 'none' }, // ซ่อน scrollbar
  }}>
        {/* สรุปสินเชื่อ */}
        {data.map((item, index) => (
  <Box key={index} sx={{ mb: 4 }}>
    {/* สรุปสินเชื่อ */}
    <Card sx={{ width: '100%' }}>
      <CardContent
        sx={{
          background: 'linear-gradient(135deg, #c8d60cff 0%, #b915b1ff 50%, #d80adfff 100%)',
          padding: 4,
          borderRadius: 0,
          color: '#FFFFFF',
          fontFamily: 'Prompt, sans-serif',
        }}
      >
        <Stack spacing={2}>
          <Typography variant="subtitle1">
            เลขที่สัญญา : {item.contractId}
          </Typography>
          <Typography variant="subtitle1">ยอดคงเหลือ</Typography>
          <Typography variant="h4">฿{item.balance.toLocaleString()}</Typography>

          <Box
            sx={{
              display: 'flex',
              flexDirection: { xs: 'column', sm: 'row' },
              justifyContent: 'space-between',
              gap: 2,
            }}
          >
            <Box>
              <Typography variant="subtitle2">เงินดาวน์</Typography>
              <Typography>฿{item.downPayment.toLocaleString()}</Typography>
            </Box>
            <Box>
              <Typography variant="subtitle2">ยอดผ่อน/เดือน</Typography>
              <Typography>฿{item.monthly.toLocaleString()}</Typography>
            </Box>
          </Box>
        </Stack>
      </CardContent>
    </Card>

    {/* ประวัติการชำระเงิน */}
    <Typography variant="h6" gutterBottom sx={{ mt: 2 }}>
      ประวัติการชำระเงิน
    </Typography>
    <Card sx={{ mb: 2 }}>
      <CardContent>
        <Stack spacing={1}>
          {item.payments.map((pay, i) => (
            <Box key={i} display="flex" justifyContent="space-between">
              <Typography>{pay.month}</Typography>
              <Typography color="primary">ชำระแล้ว ฿{pay.amount.toLocaleString()}</Typography>
            </Box>
          ))}
        </Stack>
      </CardContent>
    </Card>

    {/* เมนูการดำเนินการ */}
    <Stack
      direction={{ xs: 'column', sm: 'row' }}
      spacing={2}
      sx={{ mt: 2 }}
    >
      <Button fullWidth variant="contained" color="primary">
        ขอเพิ่มวงเงิน
      </Button>
      <Button fullWidth variant="outlined" color="primary">
        ดูรายละเอียดสัญญา
      </Button>
    </Stack>
  </Box>
))}

      </Box>
    </>
  );
};

export default LoanScreen;
